crt_screen.glsl:
shader_type canvas_item;

uniform float scanline_count : hint_range(50.0, 800.0) = 300.0;
uniform float scanline_intensity : hint_range(0.0, 1.0) = 0.15;
uniform float curvature : hint_range(0.0, 0.1) = 0.03;
uniform float vignette_intensity : hint_range(0.0, 1.0) = 0.4;
uniform float flicker_speed : hint_range(0.0, 10.0) = 3.0;
uniform float flicker_amount : hint_range(0.0, 0.1) = 0.02;
uniform float chromatic_offset : hint_range(0.0, 5.0) = 1.0;
uniform vec4 tint_color : source_color = vec4(0.9, 1.0, 0.9, 1.0);

vec2 curve_uv(vec2 uv) {
	uv = uv * 2.0 - 1.0;
	vec2 offset = abs(uv.yx) / vec2(6.0, 4.0);
	uv = uv + uv * offset * offset * curvature;
	uv = uv * 0.5 + 0.5;
	return uv;
}

void fragment() {
	vec2 uv = curve_uv(UV);

	if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
		COLOR = vec4(0.0, 0.0, 0.0, 1.0);
		return;
	}

	vec2 pixel_size = TEXTURE_PIXEL_SIZE * chromatic_offset;
	float r = texture(TEXTURE, uv + vec2(pixel_size.x, 0.0)).r;
	float g = texture(TEXTURE, uv).g;
	float b = texture(TEXTURE, uv - vec2(pixel_size.x, 0.0)).b;
	vec3 col = vec3(r, g, b);

	float scanline = sin(uv.y * scanline_count * 3.14159) * 0.5 + 0.5;
	col *= 1.0 - scanline_intensity * (1.0 - scanline);

	float flicker = 1.0 - flicker_amount * sin(TIME * flicker_speed);
	col *= flicker;

	float vignette = uv.x * uv.y * (1.0 - uv.x) * (1.0 - uv.y);
	vignette = clamp(pow(16.0 * vignette, vignette_intensity), 0.0, 1.0);
	col *= vignette;

	col *= tint_color.rgb;

	COLOR = vec4(col, 1.0);
}
